css:
#tongsci1-3-3-1-2-hill .hl-body { grid-template-columns: 1120px minmax(0, 1fr); }
#tongsci1-3-3-1-2-hill .hl-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: #f5f2ea; }
#tongsci1-3-3-1-2-hill .hl-stage canvas { touch-action: none; cursor: grab; user-select: none; -webkit-user-select: none; }
#tongsci1-3-3-1-2-hill .hl-panel { gap: 14px; }
#tongsci1-3-3-1-2-hill .hl-out { margin: 0; font-size: 21px; line-height: 1.55; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 10px 14px; min-height: 4.8em; flex: none; }
#tongsci1-3-3-1-2-hill .hl-out b { color: var(--accent); }
#tongsci1-3-3-1-2-hill .hl-tab { width: 100%; border-collapse: collapse; table-layout: fixed; font: 600 18px/1.3 var(--f-body); flex: none; background: var(--paper-2); border: 2px solid var(--ink); }
#tongsci1-3-3-1-2-hill .hl-tab thead th { font: 800 18px/1.2 var(--f-body); background: color-mix(in srgb, var(--accent) 10%, var(--paper-2)); border: 1.5px solid var(--ink-3); padding: 6px 4px; }
#tongsci1-3-3-1-2-hill .hl-tab thead th.en { color: #1d6b3a; }
#tongsci1-3-3-1-2-hill .hl-tab tbody th { font: 700 17px/1.2 var(--f-body); text-align: center; border: 1.5px solid var(--rule, #c9ccd3); background: color-mix(in srgb, var(--ink) 4%, var(--paper-2)); padding: 4px; }
#tongsci1-3-3-1-2-hill .hl-tab tbody th small { font-size: 15px; color: var(--ink-3); }
#tongsci1-3-3-1-2-hill .hl-tab td { border: 1.5px solid var(--rule, #c9ccd3); padding: 4px 6px; height: 40px; text-align: center; }
#tongsci1-3-3-1-2-hill .hl-tab td b { color: var(--accent); }
#tongsci1-3-3-1-2-hill .hl-def { margin: 0; display: grid; gap: 10px; flex: none; }
#tongsci1-3-3-1-2-hill .hl-def div { border-left: 6px solid #3fae6a; background: color-mix(in srgb, #3fae6a 9%, var(--paper-2)); border-radius: 0 10px 10px 0; padding: 8px 14px; }
#tongsci1-3-3-1-2-hill .hl-def dt { font: 800 20px var(--f-body); color: #1d6b3a; }
#tongsci1-3-3-1-2-hill .hl-def dd { margin: 2px 0 0; font-size: 19px; line-height: 1.5; }
section#tongsci1-3-3-1-2-hill.ex.u-done .hl-def { display: none; }

